from jsonb_to_recordset($dados$[{"item_group_id": "OLD-P3361", "id_loja": "3361", "nome": "Camisa Portuguesa Retrô 1968 Listrada - Masculino", "slug": "clubes/camisa-portuguesa-retro-1968-listrada-masculino", "url": "https://www.oldensports.com.br/clubes/camisa-portuguesa-retro-1968-listrada-masculino", "marca": "Retrômania", "categoria": "Camisa", "departamento": "camisas", "clube": "Portuguesa", "genero": "masculino", "faixa_etaria": "adulto", "descricao": "Camisa Portuguesa Retrô 1968 Listrada - Masculino\nA Camisa Portuguesa 1968 é um modelo clássico que remete à tradição da Lusa no futebol brasileiro, ela apresenta listras horizontais nas cores verde e vermelho, inspiradas na bandeira de Portugal. Ela possui sua gola polo em decote V, e suas mangas curtas. O design retrô traz um toque nostálgico, ideal para os torcedores que querem reviver a história do clube.\n- Produto Oficial Licenciado Portuguesa\nInformação Adicionais\nEscudo: Bordado\nTecido: 100% Algodão\nManga: Curta\nGola: Decote V, polo\nDimensões Aproximadas (A x L):\nP: 70 x 46 cm\nM: 72 x 48 cm\nG: 74 x 50 cm\nGG: 76 x 52 cm\nXG(EG): 78 x 54 cm", "medidas": null, "preco": 229.9, "preco_promocional": 196.9, "preco_pix": 187.06, "parcelamento": "6x de R$ 32,82 Sem juros", "imagens": [{"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_portuguesa_retro_1968_listrada_masculino_3361_1_302e130d51dfad1a6256ba8a5beb5d16.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_portuguesa_retro_1968_listrada_masculino_3361_2_8d0c5f43a7ad9c47bef2a0e014a988f4.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_portuguesa_retro_1968_listrada_masculino_3361_3_18ac868f186ead1d992fb4a81b4b45eb.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_portuguesa_retr_1968_listrada_masculino_4_20260706094853_64cd7beae2cc.png", "tipo": "extra"}], "video_url": null, "propriedades": {"Categoria": ["Camisa"], "Clubes": ["Portuguesa"], "Gênero": ["Masculino"]}, "lancamento": false, "destaque": false, "coletado_em": "2026-11-24T20:16:44.930870+00:00"}, {"item_group_id": "OLD-P3367", "id_loja": "3367", "nome": "Camisa Alemanha Retrô 1974 Algodão Premium Branco - Masculino", "slug": "clubes/selecoes/camisa-alemanha-retro-1974-algodao-premium-branco-masculino", "url": "https://www.oldensports.com.br/clubes/selecoes/camisa-alemanha-retro-1974-algodao-premium-branco-masculino", "marca": "Retrômania", "categoria": "Camisa", "departamento": "camisas", "clube": "Alemanha", "genero": "masculino", "faixa_etaria": "adulto", "descricao": "Camisa Alemanha Retrô 1974 Algodão Premium Branco - Masculino\nA Camisa Alemanha traz uma proposta simples, clássica e cheia de energia. Com cor predominante branca, o modelo ganha destaque pelos detalhes em preto na gola e nas mangas, criando um visual clean, esportivo e muito estiloso.\nConfeccionada em algodão premium, leve e confortável, oferece toque macio e ótimo caimento para o uso no dia a dia. Seu escudo bordado valoriza ainda mais a peça, trazendo acabamento de qualidade e identidade marcante para quem carrega a paixão pela seleção alemã.\nDetalhes do produto:\n- Tecido em algodão premium\n- Leve, macia e confortável\n- Escudo da Alemanha bordado\nMedidas Aproximadas A X L:\nP: 67 x 48CM\nM: 68 x 51CM\nG: 73 x 54CM\nGG: 74 x 57CM\nXG(EG): 77 x 61CM", "medidas": "Medidas Aproximadas A X L:\nP: 67 x 48CM\nM: 68 x 51CM\nG: 73 x 54CM\nGG: 74 x 57CM\nXG(EG): 77 x 61CM", "preco": 179.9, "preco_promocional": 66.9, "preco_pix": 63.56, "parcelamento": "6x de R$ 11,15 Sem juros", "imagens": [{"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_alemanha_retro_1974_algodao_premium_branco_masculino_3367_1_d62450c66c8d25110dfdf98bcfd488c3.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_alemanha_retro_1974_algodao_premium_branco_masculino_3367_2_7c7fe188c1fabf0f5d67aa4ff97b37ae.jpg", "tipo": "extra"}, {"ur