co": 279.9, "preco_promocional": 261.9, "preco_pix": 248.81, "parcelamento": "6x de R$ 43,65 Sem juros", "imagens": [{"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_guarani_reebok_treino_2026_atleta_verde_masculino_3371_1_a60c6268af308701da191e395ce0a077.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_guarani_reebok_treino_2026_atleta_verde_masculino_3371_2_6faa6cec037e8fb127763444c22a7d81.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_guarani_reebok_treino_2026_atleta_verde_masculino_3371_3_f092bc55e6b3b61694aaa2abe09c7b11.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_guarani_reebok_treino_2026_atleta_verde_masculino_3371_4_a8a4252be9c20b3327d506b674747035.jpg", "tipo": "extra"}], "video_url": "https://www.youtube.com/embed/CyTmolJIwjY", "propriedades": {"Categoria": ["Camisa"], "Clubes": ["Guarani"], "Gênero": ["Masculino"]}, "lancamento": false, "destaque": false, "coletado_em": "2026-11-24T20:16:44.930870+00:00"}, {"item_group_id": "OLD-P3373", "id_loja": "3373", "nome": "Camisa Argentina Balboa Celeste Azul - Masculino", "slug": "clubes/selecoes/camisa-argentina-balboa-celeste-azul-masculino", "url": "https://www.oldensports.com.br/clubes/selecoes/camisa-argentina-balboa-celeste-azul-masculino", "marca": "Balboa", "categoria": "Camisa", "departamento": "camisas", "clube": "Argentina", "genero": "masculino", "faixa_etaria": "adulto", "descricao": "Camisa Argentina Balboa Celeste Azul - Masculino\nCom visual moderno e inspirado nas cores tradicionais da seleção argentina, esta camisa combina elegância, identidade e conforto. Sua composição em poliéster com tecnologia Dry proporciona um tecido leve, respirável e de secagem rápida, ideal para o dia a dia, momentos de lazer ou para acompanhar os jogos.\nO design traz as clássicas listras verticais em azul-celeste e branco, complementadas por linhas finas que deixam a peça mais s